// A URI reference, parsed into its RFC 3986 generic components.
// Each of scheme, authority, query, fragment is either `null` (absent) or a
// string (possibly empty, meaning present-but-empty). `path` is always a
// string (never null), possibly empty.

class UriError extends Error {}

function parseReference (s) {
  let scheme = null
  let rest = s

  let colonIdx = -1
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === '/' || c === '?' || c === '#') break
    if (c === ':') { colonIdx = i; break }
  }
  if (colonIdx !== -1) {
    scheme = s.slice(0, colonIdx)
    rest = s.slice(colonIdx + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    let i = 2
    while (i < rest.length && rest[i] !== '/' && rest[i] !== '?' && rest[i] !== '#') i++
    authority = rest.slice(2, i)
    rest = rest.slice(i)
  }

  let i = 0
  while (i < rest.length && rest[i] !== '?' && rest[i] !== '#') i++
  const path = rest.slice(0, i)
  rest = rest.slice(i)

  let query = null
  if (rest.startsWith('?')) {
    let j = 1
    while (j < rest.length && rest[j] !== '#') j++
    query = rest.slice(1, j)
    rest = rest.slice(j)
  }

  let fragment = null
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

function splitAuthority (auth) {
  const lastAt = auth.lastIndexOf('@')
  let userinfo = null
  let rest = auth
  if (lastAt !== -1) {
    userinfo = auth.slice(0, lastAt)
    rest = auth.slice(lastAt + 1)
  }
  const lastBracket = rest.lastIndexOf(']')
  const searchFrom = lastBracket + 1
  const colonIdx = rest.indexOf(':', searchFrom)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
    port = null
  }
  return { userinfo, host, port }
}

function serialize (p) {
  let out = ''
  if (p.scheme !== null) out += p.scheme + ':'
  if (p.authority !== null) out += '//' + p.authority
  out += p.path
  if (p.query !== null) out += '?' + p.query
  if (p.fragment !== null) out += '#' + p.fragment
  return out
}

function isHex (c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isUnreserved (ch) {
  return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') ||
    (ch >= '0' && ch <= '9') || ch === '-' || ch === '.' || ch === '_' || ch === '~'
}

function pctNormalize (s, component) {
  let out = ''
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === '%') {
      if (i + 2 >= s.length || !isHex(s[i + 1]) || !isHex(s[i + 2])) {
        throw new UriError(`the ${component} has a truncated percent-encoding`)
      }
      const hex = s.slice(i + 1, i + 3).toUpperCase()
      const code = parseInt(hex, 16)
      const ch = String.fromCharCode(code)
      if (isUnreserved(ch)) {
        out += ch
      } else {
        out += '%' + hex
      }
      i += 3
    } else {
      out += c
      i++
    }
  }
  return out
}

function asciiLower (s) {
  let out = ''
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    out += (c >= 'A' && c <= 'Z') ? String.fromCharCode(c.charCodeAt(0) + 32) : c
  }
  return out
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function removeDotSegments (path) {
  let input = path
  let output = ''
  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '/..') {
      input = '/'
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const match = input.match(/^\/?[^/]*/)[0]
      output += match
      input = input.slice(match.length)
    }
  }
  return output
}

function normalizeParsed (parsed) {
  const { scheme, authority, path, query, fragment } = parsed

  const schemeLower = scheme !== null ? asciiLower(scheme) : null

  let userinfo = null
  let host = null
  let port = null
  if (authority !== null) {
    const split = splitAuthority(authority)
    userinfo = split.userinfo
    host = split.host
    port = split.port
  }

  // Checked in this order: path, userinfo, host, query, fragment.
  const pathN = pctNormalize(path, 'path')
  const userinfoN = userinfo !== null ? pctNormalize(userinfo, 'userinfo') : null
  let hostN = host !== null ? pctNormalize(host, 'host') : null
  const queryN = query !== null ? pctNormalize(query, 'query') : null
  const fragmentN = fragment !== null ? pctNormalize(fragment, 'fragment') : null

  if (hostN !== null) hostN = asciiLower(hostN)

  let portOut = port
  if (port !== null) {
    if (port === '') {
      portOut = null
    } else if (schemeLower !== null && DEFAULT_PORTS[schemeLower] === port) {
      portOut = null
    } else {
      portOut = port
    }
  }

  let authorityOut = null
  if (authority !== null) {
    authorityOut = (userinfoN !== null ? userinfoN + '@' : '') + hostN + (portOut !== null ? ':' + portOut : '')
  }

  let pathOut = removeDotSegments(pathN)
  if (authorityOut !== null && pathOut === '') pathOut = '/'

  return { scheme: schemeLower, authority: authorityOut, path: pathOut, query: queryN, fragment: fragmentN }
}

function merge (base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

function resolveTarget (base, ref) {
  const t = {}
  if (ref.scheme !== null) {
    t.scheme = ref.scheme
    t.authority = ref.authority
    t.path = ref.path
    t.query = ref.query
  } else {
    if (ref.authority !== null) {
      t.authority = ref.authority
      t.path = ref.path
      t.query = ref.query
    } else {
      if (ref.path === '') {
        t.path = base.path
        t.query = ref.query !== null ? ref.query : base.query
      } else {
        if (ref.path.startsWith('/')) {
          t.path = ref.path
        } else {
          t.path = merge(base, ref.path)
        }
        t.query = ref.query
      }
      t.authority = base.authority
    }
    t.scheme = base.scheme
  }
  t.fragment = ref.fragment
  return t
}

function normalizeString (line) {
  const parsed = parseReference(line)
  return serialize(normalizeParsed(parsed))
}

function resolveString (baseStr, refStr) {
  const base = parseReference(baseStr)
  const ref = parseReference(refStr)
  const target = resolveTarget(base, ref)
  return serialize(normalizeParsed(target))
}

module.exports = { parseReference, normalizeString, resolveString, UriError }
"}

