{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { normalizeString, resolveString, UriError } from './uri.js'

function readStdin () {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main () {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = await readStdin()
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        results.push(normalizeString(line))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          process.stderr.write(`error: line ${lineNum}: expected a base and a reference\n`)
          process.exit(2)
        }
        const baseStr = line.slice(0, spaceIdx)
        const refStr = line.slice(spaceIdx + 1)
        // Check base has a scheme before anything else.
        const colonIdx = (() => {
          for (let j = 0; j < baseStr.length; j++) {
            const c = baseStr[j]
            if (c === '/' || c === '?' || c === '#') return -1
            if (c === ':') return j
          }
          return -1
        })()
        if (colonIdx === -1) {
          process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`)
          process.exit(2)
        }
        results.push(resolveString(baseStr, refStr))
      }
    } catch (e) {
      if (e instanceof UriError) {
        process.stderr.write(`error: line ${lineNum}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }

  process.stdout.write(results.map((r) => r + '\n').join(''))
  process.exit(0)
}

main()
"}

